// blockFallSounds is blockFallSoundNames resolved to clientbound
// registry ids through soundEventIDs.
var blockFallSounds = func() map[string]int32 {
	m := make(map[string]int32, len(blockFallSoundNames))
	for n, snd := range blockFallSoundNames {
		if id, ok := soundEventIDs[snd]; ok {
			m[n] = id
		}
	}
	return m
}()
